#!/bin/sh
# Print the top 3 most frequent IP addresses in access.log, one per line,
# most frequent first; ties are broken by first appearance in the log.
set -eu
cd "$(dirname "$0")"

awk '
{
    # Extract an IPv4 address if the line contains one, otherwise use the
    # first field (e.g. a bare IP in a minimal log format).
    ip = ""
    if (match($0, /[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+/))
        ip = substr($0, RSTART, RLENGTH)
    else
        ip = $1

    count[ip]++
    if (!(ip in first))
        first[ip] = ++n
}
END {
    for (i = 1; i <= n; i++) {
        for (ip in count) {
            if (first[ip] == i) { print count[ip] "\t" ip; break }
        }
    }
}
' access.log \
| sort -t "$(printf '\t')" -k1,1nr -k2,2 \
| head -n 3 \
| cut -f2
